function illustrationScene(topic: string, question: string): string {
  const specificScene = questionScenes[question];
  if (specificScene) return specificScene;
  const text = question.toLowerCase();
  if (topic === "risk") {
    if (text.includes("var auf") || text.includes("value at risk")) return "value-at-risk";
    if (text.includes("expected shortfall")) return "expected-shortfall";
    if (text.includes("20.000") || text.includes("geldrisiko")) return "trade-risk-budget";
    if (text.includes("tail") || text.includes("seltene")) return "tail-risk";
    if (text.includes("beta")) return "beta-market-sensitivity";
    if (text.includes("cashflows")) return "earnings-cashflow-gap";
    return "portfolio-stress-correlation";
  }
  if (topic === "valuation") {
    if (text.includes("zyklische")) return "cyclical-earnings-valuation";
    if (text.includes("kgv") || text.includes("kurs-gewinn")) return "pe-ratio-calculation";
    if (text.includes("terminalwachstum")) return "terminal-growth-valuation";
    if (text.includes("diskontsatz")) return "discount-rate-cashflows";
    if (text.includes("sum-of-the-parts")) return "segment-valuation";
  }
  if (topic === "portfolio") {
    if (text.includes("60 %") || text.includes("rendite 5 %")) return "weighted-portfolio-return";
    if (text.includes("rebalanced")) return "portfolio-rebalancing";
    if (text.includes("delta-neutral")) return "delta-gamma-hedging";
    if (text.includes("korrelieren") || text.includes("krisen")) return "crisis-correlation";
    return "diversified-investment-portfolio";
  }
  if (topic === "stablecoin" && text.includes("gedeckt")) return "stablecoin-reserves";
  if (topic === "consensus" && text.includes("finalität")) return "blockchain-finality";
  if (topic === "bridge" && text.includes("sperrt token")) return "wrapped-token-bridge";
  if (topic === "governance" && text.includes("geringer beteiligung")) return "governance-voter-turnout";
  if (topic === "governance" && text.includes("duales aktienklassensystem")) return "dual-class-share-control";
  if (topic === "security" && text.includes("audit")) return "smart-contract-audit";
  if (topic === "fiscal" && text.includes("automatische stabilisatoren")) return "automatic-fiscal-stabilizers";
  if (topic === "fiscal" && text.includes("staatsschulden")) return "debt-growth-interest-dynamics";
  if (topic === "exchange" && text.includes("freies kapital")) return "impossible-trinity";
  if (topic === "exchange" && text.includes("verteidigt einen festen")) return "fixed-exchange-rate-defense";
  if (topic === "exchange" && text.includes("wertet ab")) return "currency-depreciation-imports";
  if (topic === "rates" && text.includes("langfristige renditen")) return "policy-rate-yield-curve";
  if (topic === "rates" && text.includes("effektiven untergrenze")) return "lower-bound-monetary-policy";
  if (topic === "inflation" && text.includes("basisperiode")) return "rebased-price-index";
  if (topic === "inflation" && text.includes("kerninflation")) return "core-and-headline-inflation";
  if (topic === "inflation" && text.includes("kaufkraft")) return "real-purchasing-power";
  if (topic === "mortgage" && text.includes("variabel verzinsten")) return "variable-rate-mortgage";
  if (topic === "backtest" && text.includes("survivorship")) return "survivorship-bias";
  if (topic === "backtest" && text.includes("parameterkombinationen")) return "overfit-backtest";
  if (topic === "liquidity" && text.includes("korrelationen stabil")) return "crisis-correlation";
  if (topic === "liquidity" && text.includes("orderbuch")) return "order-book-depth";
  if (topic === "options" && text.includes("ungedeckte calls")) return "uncovered-call-risk";
  if (topic === "governance" && text.includes("handelsmodell")) return "walk-forward-validation";
  return topic;
}

function q(art: string, deQuestion: string, enQuestion: string, deAnswers: string, enAnswers: string, correctAnswer: number, deExplanation: string, enExplanation: string): BilingualQuestion {
  const answers = (value: string) => value.split("|") as BilingualQuestion["de"]["answers"];
  const artworkId = `${art}-${++artworkOrder}`;
  return {
    id: stableQuestionId(deQuestion),
    art: artworkId,
    scene: illustrationScene(art, deQuestion),
    de: { question: deQuestion, answers: answers(deAnswers), explanation: deExplanation },
    en: { question: enQuestion, answers: answers(enAnswers), explanation: enExplanation },
    correctAnswer,
  };
}

